#!/usr/bin/env node
/**
 * The exact text of every mutation, printed from the spec files that ran it.
 *
 * A mutation table says what an injection did and which test killed it. The
 * eighth part of the evidence standard asks for the injection itself, quoted,
 * so a reader can see the change rather than a description of it. Writing that
 * by hand would be a second copy of the spec files and would drift from them
 * the first time a row was re-aimed — so it is generated, and a test fails if
 * the generated file and the specs disagree.
 *
 *   node scripts/emit-mutation-edits.mjs            # write docs/tdd/sweeps/EDITS.md
 *   node scripts/emit-mutation-edits.mjs --check    # exit 1 if it is stale
 */
import fs from 'node:fs';
import path from 'node:path';

const DIR = 'docs/tdd/sweeps';
const OUT = path.join(DIR, 'EDITS.md');

/** Which evidence file each spec belongs to, so a reader can get back. */
const EVIDENCE = {
  catalog: 'coach-catalog-and-select.tdd.md',
  ledger: 'coach-ledger-and-verifier.tdd.md',
  tools: 'coach-tool-layer.tdd.md',
  ask: 'coach-answering-loop.tdd.md',
  lexicon: 'coach-stat-lexicon.tdd.md',
  person: 'coach-person-profile.tdd.md',
  grading: 'coach-person-grading.tdd.md',
  creators: 'coach-table-origins.tdd.md',
  'page-explain': 'page-explain-assertions.tdd.md'
};

const fence = text => '```\n' + text.replace(/\n$/, '') + '\n```';

export function render() {
  const out = [
    '# The exact edit behind every mutation row',
    '',
    'Generated by `scripts/emit-mutation-edits.mjs` from the spec files beside it, which are',
    'the same files the harness runs. Do not edit this by hand: a test compares it against',
    'the specs and fails if they disagree, so a row re-aimed in a spec shows up here or the',
    'suite goes red.',
    '',
    'Each row shows the literal text replaced and the literal text it was replaced with. The',
    'harness requires the "before" text to appear exactly once in the file, so an injection',
    'that no longer matches is reported NOT APPLIED rather than scoring zero failures.',
    ''
  ];
  for (const [spec, evidence] of Object.entries(EVIDENCE)) {
    const file = path.join(DIR, `${spec}.json`);
    if (!fs.existsSync(file)) continue;
    const rows = JSON.parse(fs.readFileSync(file, 'utf8'));
    out.push(`## \`${spec}.json\` — ${rows.length} rows, evidence in \`docs/tdd/${evidence}\``, '');
    for (const row of rows) {
      // `files` is the harness's two-file form; everything else is one file
      // and renders exactly as it always did.
      const groups = row.files ?? [{ file: row.file, edits: row.edits ?? [[row.old, row.new]] }];
      const where = groups.map(group => `\`${group.file}\``).join(' and ');
      out.push(`### ${row.id} — ${row.desc}`, '', `${where}, suites \`${row.tests}\``, '');
      for (const group of groups) {
        if (groups.length > 1) out.push(`in \`${group.file}\`:`, '');
        for (const [before, after] of group.edits) {
          out.push('before:', fence(before), 'after:', fence(after === '' ? '(the line is removed)' : after), '');
        }
      }
    }
  }
  return `${out.join('\n').replace(/\n+$/, '')}\n`;
}

const rendered = render();
if (process.argv.includes('--check')) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== rendered) {
    console.error(`${OUT} is stale. Run: node scripts/emit-mutation-edits.mjs`);
    process.exit(1);
  }
  console.log(`${OUT} matches the spec files.`);
} else if (process.argv[1] && process.argv[1].endsWith('emit-mutation-edits.mjs')) {
  fs.writeFileSync(OUT, rendered);
  console.log(`wrote ${OUT}`);
}
